-- Start from an empty template so no objects leak in
CREATE DATABASE inventory
  WITH OWNER = app_user
       ENCODING = 'UTF8'
       TEMPLATE = template0;

-- A schema keeps reporting objects away from the public schema
CREATE SCHEMA reporting AUTHORIZATION app_user;

-- New sessions of this role resolve unqualified names in this order
ALTER ROLE app_user SET search_path = public, reporting;

-- Databases and their size on disk
SELECT datname,
       pg_size_pretty(pg_database_size(datname)) AS size
FROM pg_database
ORDER BY pg_database_size(datname) DESC;

-- Application schemas only
SELECT schema_name, schema_owner
FROM information_schema.schemata
WHERE schema_name NOT IN ('pg_catalog', 'information_schema');

-- Drop even when sessions are connected (PostgreSQL 13+)
DROP DATABASE IF EXISTS inventory_old WITH (FORCE);

-- Defaults applied to every new session on this database
ALTER DATABASE inventory SET timezone = 'UTC';
ALTER DATABASE inventory SET statement_timeout = '30s';

CREATE TABLE customers (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email       text NOT NULL UNIQUE,
  display_name text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE orders (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id  bigint NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
  status       text NOT NULL DEFAULT 'pending'
                 CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),
  total_cents  integer NOT NULL CHECK (total_cents >= 0),
  placed_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX orders_customer_idx ON orders (customer_id);

-- Add a nullable column; existing rows get NULL without a rewrite
ALTER TABLE orders ADD COLUMN shipped_at timestamptz;

-- Nothing may ship before it was placed
ALTER TABLE orders
  ADD CONSTRAINT orders_shipped_after_placed
  CHECK (shipped_at IS NULL OR shipped_at >= placed_at);

ALTER TABLE customers RENAME COLUMN display_name TO full_name;

-- Remove every row and restart the identity counter
TRUNCATE orders RESTART IDENTITY CASCADE;

-- Monthly partitions keep old data cheap to drop
CREATE TABLE events (
  id          bigint NOT NULL,
  occurred_at timestamptz NOT NULL,
  payload     jsonb NOT NULL,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);

CREATE TABLE events_2026_11 PARTITION OF events
  FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

CREATE TABLE events_2026_12 PARTITION OF events
  FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');

CREATE TYPE order_status AS ENUM ('pending', 'paid', 'shipped', 'cancelled');

CREATE DOMAIN positive_cents AS integer CHECK (VALUE > 0);

CREATE TABLE shipments (
  id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  status    order_status NOT NULL DEFAULT 'pending',
  fee_cents positive_cents NOT NULL
);

SELECT id,
       customer_id,
       placed_at,
       placed_at - lag(placed_at) OVER (
         PARTITION BY customer_id ORDER BY placed_at
       ) AS gap_since_previous,
       lead(total_cents, 1, 0) OVER (
         PARTITION BY customer_id ORDER BY placed_at
       ) AS next_total
FROM orders;

-- Window functions are filtered after they run, so wrap them
SELECT *
FROM (
  SELECT o.*,
         row_number() OVER (
           PARTITION BY customer_id ORDER BY placed_at DESC
         ) AS rn
  FROM orders AS o
) AS ranked
WHERE rn <= 3;

-- Composite index for the common filter plus order
CREATE INDEX orders_customer_placed_idx
  ON orders (customer_id, placed_at DESC);

-- Partial index: only pending rows are stored
CREATE INDEX orders_pending_idx
  ON orders (placed_at)
  WHERE status = 'pending';

-- Expression index for case-insensitive lookups
CREATE INDEX customers_lower_email_idx
  ON customers (lower(email));

-- Build without blocking writes; cannot run inside a transaction
CREATE INDEX CONCURRENTLY orders_status_idx ON orders (status);

-- Rebuild without blocking reads or writes
REINDEX INDEX CONCURRENTLY orders_customer_placed_idx;

DROP INDEX CONCURRENTLY IF EXISTS orders_status_idx;

-- GIN for JSONB containment queries
CREATE INDEX events_payload_idx
  ON events USING gin (payload jsonb_path_ops);

-- GIN for full-text search over a generated column
ALTER TABLE articles
  ADD COLUMN search tsvector
  GENERATED ALWAYS AS (to_tsvector('english', body)) STORED;

CREATE INDEX articles_search_idx ON articles USING gin (search);

BEGIN;

UPDATE accounts SET balance_cents = balance_cents - 2500 WHERE id = 1;
UPDATE accounts SET balance_cents = balance_cents + 2500 WHERE id = 2;

COMMIT;

-- Undo everything since BEGIN
BEGIN;
DELETE FROM orders WHERE status = 'cancelled';
ROLLBACK;

-- Serializable may abort; the client retries on SQLSTATE 40001
BEGIN ISOLATION LEVEL SERIALIZABLE;
UPDATE accounts SET balance_cents = balance_cents - 100 WHERE id = 1;
COMMIT;

BEGIN;

INSERT INTO customers (email, full_name)
VALUES ('new@example.com', 'New Customer');

SAVEPOINT before_cleanup;

DELETE FROM orders WHERE customer_id = 9001;

-- Undo only the delete, keep the insert before the savepoint
ROLLBACK TO SAVEPOINT before_cleanup;
RELEASE SAVEPOINT before_cleanup;

COMMIT;

-- LOGIN allows a connection; the password is stored as a SCRAM hash
CREATE ROLE app_user LOGIN PASSWORD 'devsecret';
CREATE ROLE reporting NOLOGIN;
CREATE ROLE deploy IN ROLE app_user;

-- Change a password interactively without shell history
-- psql: \password app_user

-- A contractor account that stops working at the end of the month
CREATE ROLE contractor LOGIN PASSWORD 'temp-pass-2026'
  VALID UNTIL '2026-11-30';

GRANT CONNECT ON DATABASE inventory TO app_user;
GRANT USAGE ON SCHEMA public TO app_user;

GRANT SELECT, INSERT, UPDATE, DELETE
  ON ALL TABLES IN SCHEMA public
  TO app_user;

GRANT USAGE, SELECT
  ON ALL SEQUENCES IN SCHEMA public
  TO app_user;

-- Future tables created by this role get read access for reporting
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT ON TABLES TO reporting;

-- Read-only role: all data readable, nothing writable (PostgreSQL 14+)
GRANT pg_read_all_data TO reporting;

-- Remove the default world access from the public schema
REVOKE ALL ON SCHEMA public FROM PUBLIC;

-- Verify instead of guessing
SELECT has_table_privilege('app_user', 'public.orders', 'UPDATE') AS can_update;

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Trigram search backs LIKE, ILIKE and the % operator
SELECT similarity('postgresql', 'postgres') AS score,
       'postgres' % 'postgre' AS matches;

CREATE INDEX customers_email_trgm_idx
  ON customers USING gin (email gin_trgm_ops);

-- pg_stat_statements must be preloaded before it can start
ALTER SYSTEM SET shared_preload_libraries = 'pg_stat_statements';
-- restart the server, then create the extension
CREATE EXTENSION IF NOT EXISTS pg_stat_statements;

-- pgcrypto adds hashing and encryption functions
CREATE EXTENSION IF NOT EXISTS pgcrypto;
SELECT encode(digest('devsecret', 'sha256'), 'hex') AS hex_digest;

-- duplicate key value violates unique constraint "customers_email_key"
INSERT INTO customers (email, full_name)
VALUES ('ana@example.com', 'Ana Souza')
ON CONFLICT (email) DO UPDATE
SET full_name = EXCLUDED.full_name
RETURNING id;

-- permission denied for table orders
SELECT has_table_privilege('app_user', 'public.orders', 'SELECT') AS can_read;
GRANT SELECT ON public.orders TO app_user;

-- canceling statement due to statement timeout
SHOW statement_timeout;
SET statement_timeout = '60s';

-- too many connections for role "app_user"
SHOW max_connections;
SELECT count(*) AS open_connections FROM pg_stat_activity;

-- could not serialize access due to concurrent update
BEGIN ISOLATION LEVEL REPEATABLE READ;
-- retry the whole transaction from the client when SQLSTATE 40001 is returned
COMMIT;
